import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry conv_transpose2d_kernel(
    .param .u64 p_x,
    .param .u64 p_w,
    .param .u64 p_bias,
    .param .u64 p_out,
    .param .u32 n_h_in,
    .param .u32 n_w_in,
    .param .u32 n_h_out,
    .param .u32 n_w_out,
    .param .u32 n_total,
    .param .u32 n_has_bias
)
{
    .reg .pred %p;
    .reg .b32 %r<40>;
    .reg .b64 %rd<10>;
    .reg .f32 %f<8>;

    // global thread id
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.s32 %r4, %r1, %r2, %r3;
    ld.param.u32 %r5, [n_total];
    setp.ge.u32 %p, %r4, %r5;
    @%p bra DONE;

    // load params
    ld.param.u32 %r6, [n_w_out];
    ld.param.u32 %r7, [n_h_out];
    ld.param.u32 %r18, [n_h_in];
    ld.param.u32 %r19, [n_w_in];
    ld.param.u64 %rd1, [p_x];
    ld.param.u64 %rd2, [p_w];
    ld.param.u64 %rd4, [p_out];

    // decompose tid -> (b, oc, h, w), NCHW contiguous
    div.u32 %r8, %r4, %r6;
    rem.u32 %r9, %r4, %r6;
    div.u32 %r10, %r8, %r7;
    rem.u32 %r11, %r8, %r7;
    and.b32 %r12, %r10, 63;
    shr.u32 %r13, %r10, 6;
    shr.u32 %r14, %r12, 4;
    and.b32 %r15, %r12, 15;
    shl.b32 %r16, %r14, 3;
    shl.b32 %r17, %r13, 5;

    mov.f32 %f1, 0f00000000;

    mov.u32 %r20, 0;
KH_LOOP:
    setp.ge.s32 %p, %r20, 3;
    @%p bra KH_DONE;
    // t = h + pad_h - kh*dil_h = h + 1 - 2*kh
    shl.b32 %r21, %r20, 1;
    sub.s32 %r21, %r11, %r21;
    add.s32 %r21, %r21, 1;
    setp.lt.s32 %p, %r21, 0;
    @%p bra KH_NEXT;
    and.b32 %r22, %r21, 1;
    setp.ne.u32 %p, %r22, 0;
    @%p bra KH_NEXT;
    shr.u32 %r23, %r21, 1;
    setp.ge.u32 %p, %r23, %r18;
    @%p bra KH_NEXT;

    mov.u32 %r24, 0;
KW_LOOP:
    setp.ge.s32 %p, %r24, 5;
    @%p bra KW_DONE;
    // u = w + pad_w - kw*dil_w = w + 2 - kw
    sub.s32 %r25, %r9, %r24;
    add.s32 %r25, %r25, 2;
    setp.lt.s32 %p, %r25, 0;
    @%p bra KW_NEXT;
    div.u32 %r26, %r25, 3;
    mul.lo.u32 %r27, %r26, 3;
    sub.s32 %r28, %r25, %r27;
    setp.ne.u32 %p, %r28, 0;
    @%p bra KW_NEXT;
    setp.ge.u32 %p, %r26, %r19;
    @%p bra KW_NEXT;

    mov.u32 %r29, 0;
IC_LOOP:
    setp.ge.s32 %p, %r29, 8;
    @%p bra IC_DONE;
    add.s32 %r30, %r16, %r29;
    // xoff = ((b*32 + ic)*H_in + hi)*W_in + wi
    add.s32 %r31, %r17, %r30;
    mad.lo.s32 %r31, %r31, %r18, %r23;
    mad.lo.s32 %r32, %r31, %r19, %r26;
    // woff = ((ic*16 + oc_local)*3 + kh)*5 + kw
    shl.b32 %r33, %r30, 4;
    add.s32 %r33, %r33, %r15;
    mad.lo.s32 %r33, %r33, 3, %r20;
    mad.lo.s32 %r34, %r33, 5, %r24;

    mad.wide.u32 %rd5, %r32, 4, %rd1;
    ld.global.f32 %f2, [%rd5];
    mad.wide.u32 %rd6, %r34, 4, %rd2;
    ld.global.f32 %f3, [%rd6];
    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.s32 %r29, %r29, 1;
    bra IC_LOOP;
IC_DONE:
KW_NEXT:
    add.s32 %r24, %r24, 1;
    bra KW_LOOP;
KW_DONE:
KH_NEXT:
    add.s32 %r20, %r20, 1;
    bra KH_LOOP;
KH_DONE:

    ld.param.u32 %r35, [n_has_bias];
    setp.eq.u32 %p, %r35, 0;
    @%p bra STORE;
    ld.param.u64 %rd3, [p_bias];
    mad.wide.u32 %rd7, %r12, 4, %rd3;
    ld.global.f32 %f4, [%rd7];
    add.f32 %f1, %f1, %f4;
STORE:
    mad.wide.u32 %rd8, %r4, 4, %rd4;
    st.global.f32 [%rd8], %f1;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose2d = nn.ConvTranspose2d(in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        conv = self.conv_transpose2d
        x = x.contiguous()
        weight = conv.weight.contiguous()
        bias = conv.bias

        batch, _, h_in, w_in = x.shape
        sh, sw = self.stride
        ph, pw = self.padding
        dh, dw = self.dilation
        kh, kw = self.kernel_size
        h_out = (h_in - 1) * sh - 2 * ph + dh * (kh - 1) + 1
        w_out = (w_in - 1) * sw - 2 * pw + dw * (kw - 1) + 1

        out = torch.empty((batch, self.out_channels, h_out, w_out), dtype=x.dtype, device=x.device)
        total = batch * self.out_channels * h_out * w_out

        has_bias = 1 if bias is not None else 0
        bias_arg = bias.contiguous() if bias is not None else weight

        module = _get_ptx_module()
        threads = 256
        grid_x = (total + threads - 1) // threads
        module.launch(
            "conv_transpose2d_kernel",
            grid=(grid_x, 1, 1),
            block=(threads, 1, 1),
            arguments=[x, weight, bias_arg, out, i32(h_in), i32(w_in), i32(h_out), i32(w_out), i32(total), i32(has_bias)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

